# RW2DM_ORIENTONCRV: OrientOnCrv: place objects along a curve and orient them to the curve. The script is rw2dm_orientoncrv_script.txt; generated by rw2dm_gen.py (the closed forms are in that file). Every object kind of the case (Point, Line, Plane, Box) is
# compared with the closed-form image of the operation: points by the residual move to the origin (printed 0,0,0 within 1e-9), curve / surface control points
# through ExtractPt the same way, boxes by their bounding box after a residual move. RW2DM_ORIENTONCRV_sensitivity shows that a 1e-6 error would read 1e-06.
RW2_ORIENTONCRV_OUT=""
rw2_orientoncrv_run() {
  local o
  if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
    o="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_ORIENTONCRV_run: $1 exited non-zero"; fail=1; o=""; }
  else
    o="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_ORIENTONCRV_run: $1 exited non-zero"; fail=1; o=""; }
  fi
  RW2_ORIENTONCRV_OUT+="$o"$'\n'
}
rw2_orientoncrv_run rw2dm_orientoncrv_script.txt
rw2_orientoncrv_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_ORIENTONCRV_OUT"; }
# rw2_orientoncrv_resid NAME NPTS BOXES DESC: the case listed exactly NPTS points, every one at residual 0,0,0, and the boxes' bounding boxes (joined by ';') read exactly BOXES
rw2_orientoncrv_resid() {
  local blk npts zeros boxes; blk="$(rw2_orientoncrv_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  boxes="$({ grep -E '^history: Bounding box min ' <<<"$blk" || true; } | sed -E 's/^history: Bounding box //' | paste -sd';' -)"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ] && [ "$boxes" = "$3" ]; then echo "ok   RW2DM_ORIENTONCRV_$1: $4 ($2 points at residual 0 within 1e-9; boxes: ${3:-none})"
  else echo "FAIL RW2DM_ORIENTONCRV_$1: $4 (listed $npts points, $zeros at residual 0, expected $2 and $2; boxes '$boxes', expected '$3')"; fail=1; { grep -E '^history:   |^history: Bounding box|^history: ! ' <<<"$blk" || true; } | head -16 | sed 's/^/     residual: /'; fi
}
rw2_orientoncrv_resid copies 23 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "OrientOnCrv onto the line (10,0,0)-(10,12,0) at the picks (10,3,0) and (10,9,0), base (0,0,0): the frame x = tangent, y = up cross x maps the base frame; originals stay, one copy per pick"
rw2_orientoncrv_resid perp 16 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "OrientOnCrv Perpendicular=Yes: the object's z axis becomes the curve tangent (x = up made perpendicular to the tangent)"
rw2_orientoncrv_resid slant 9 "min 0,0,0 max 2.8,2.8,2" "OrientOnCrv Copy=No onto the slanted line (10,0,0)-(16,8,0) at its midpoint (13,4,0): the objects themselves are turned to tangent (0.6,0.8,0) and moved there"
# negative control: the same harness must SEE a 1e-6 error (a point 1e-6 off its expected image reads 1e-06, not 0)
rw2_orientoncrv_sens() {
  local blk; blk="$(rw2_orientoncrv_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RW2DM_ORIENTONCRV_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RW2DM_ORIENTONCRV_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rw2_orientoncrv_sens
